package com.medicore.payment.entity; import jakarta.persistence.*; import java.math.BigDecimal; @Entity @Table(name="payments") public class Payment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long orderId; @Column(nullable=false) private BigDecimal amount; @Column(nullable=false) private String status="PENDING"; protected Payment(){} public Payment(Long orderId,BigDecimal amount){this.orderId=orderId;this.amount=amount;} public Long getId(){return id;} public Long getOrderId(){return orderId;} public BigDecimal getAmount(){return amount;} public String getStatus(){return status;} public void setStatus(String s){status=s;}}
